# requires-python = ">=3.9"
# dependencies = ["pyyaml"]
# ///
"""Write dac/INDEX.md, the one-table view of every obligation. Generated: do not edit INDEX.md by hand.

    uv run scripts/index.py
"""
from lint import ROOT, load_obligations, load_vocab


def enforced(e):
    parts = [f"{len(e['shift_left'])} SL"] if e.get("shift_left") else []
    parts += [f"{len(e['proposed'])} proposed"] if e.get("proposed") else []
    parts += ["runtime"] if e.get("runtime") else []
    parts += ["review"] if e.get("review") else []
    parts += ["**gap**"] if not (e.get("shift_left") or e.get("proposed")) else []
    return ", ".join(parts)


def render():
    names = load_vocab()["concerns"]
    recs = sorted(load_obligations(), key=lambda r: (int(r["concern"][1:]), r["id"]))
    core = sum(r["core"] for r in recs)
    out = ["# DAC index", "",
           f"Generated by `scripts/index.py` from `dac/obligations/`. {len(recs)} obligations, {core} of them core.",
           "", "Enforced by: shift-left checks (SL), proposed checks not in the bundle yet, the runtime test, review. "
           "**gap** means no build-time check yet.",
           "", "| Id | Concern | Level | Core | Title | Came from | Enforced by |", "|---|---|---|---|---|---|---|"]
    for r in recs:
        if r.get("review_check"):
            src = f"Tech check {r['review_check']}"
        elif r.get("origin") == "deck":
            src = "New (deck decision)"
        elif r.get("origin") == "shape":
            src = "New (shape decision, ADR or DPC)"
        else:
            src = f"New ({r.get('plan_rule') or 'reuse delta'})"
        out.append(f"| {r['id']} | {r['concern']} {names[r['concern']]['name']} | {r['level']} | "
                   f"{'yes' if r['core'] else ''} | {r['title']} | {src} | {enforced(r.get('enforced_by') or {})} |")
    return "\n".join(out) + "\n"


if __name__ == "__main__":
    (ROOT / "dac" / "INDEX.md").write_text(render())
    print("wrote dac/INDEX.md")
